public class TimelineFeedMerger {
    private final Comparator<Post> postComparator = Comparator.comparingLong(Post::getTimestamp).reversed();

    public List<Post> mergeTimelines(List<Iterator<Post>> userStreams, int limit) {
        PriorityQueue<BufferedIterator> minHeap = new PriorityQueue<>(
            Comparator.comparing(bi -> bi.current, (p1, p2) -> postComparator.compare(p2, p1))
        );

        for (Iterator<Post> stream : userStreams) {
            if (stream.hasNext()) {
                minHeap.offer(new BufferedIterator(stream));
            }
        }

        List<Post> result = new ArrayList<>(limit);
        while (!minHeap.isEmpty() && result.size() < limit) {
            BufferedIterator bi = minHeap.poll();
            result.add(bi.current);
            if (bi.iterator.hasNext()) {
                bi.current = bi.iterator.next();
                minHeap.offer(bi);
            }
        }
        return result;
    }

    private static class BufferedIterator {
        private final Iterator<Post> iterator;
        private Post current;
        BufferedIterator(Iterator<Post> iterator) {
            this.iterator = iterator;
            this.current = iterator.next();
        }
    }
}
